using System;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Threading;
using System.Threading.Tasks;

internal sealed class UpdateDialog:Form {
 readonly Label status=new Label();readonly TextBox notes=new TextBox();readonly ProgressBar progress=new ProgressBar();readonly Button check=new Button(),install=new Button(),cancel=new Button();readonly string target,data;readonly Func<string,Task<bool>> start;CancellationTokenSource cancellation;ReleaseInfo release;bool working;
 internal UpdateDialog(string installDir,string dataDir,Func<string,Task<bool>> begin){target=installDir;data=dataDir;start=begin;Text="软件更新";Font=new Font("Microsoft YaHei UI",9.5f);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;ClientSize=new Size(640,420);ShowInTaskbar=false;
  var title=new Label{Text="订单工作台 · 软件更新",Font=new Font(Font.FontFamily,14,FontStyle.Bold),AutoSize=true,Location=new Point(22,20)};var current=new Label{Text="当前版本 v"+UpdateCore.VersionText+" · 更新后保留本机订单与文件关联",AutoSize=true,Location=new Point(24,60),ForeColor=Color.DimGray};status.Location=new Point(24,91);status.Size=new Size(588,45);status.Text="点击检查更新，获取 GitHub 上最新的正式版本。";notes.SetBounds(24,140,590,170);notes.Multiline=true;notes.ReadOnly=true;notes.ScrollBars=ScrollBars.Vertical;notes.BackColor=Color.White;notes.Text="更新来自 HVTMRZ-A/order-workbench。下载后会校验文件，确认保存后自动关闭、更新并重新打开。";progress.SetBounds(24,322,590,14);check.Text="检查更新";check.SetBounds(235,360,118,36);install.Text="下载并更新";install.SetBounds(365,360,118,36);install.Enabled=false;cancel.Text="关闭";cancel.SetBounds(495,360,118,36);Controls.AddRange(new Control[]{title,current,status,notes,progress,check,install,cancel});check.Click+=async delegate{await Check();};install.Click+=async delegate{await Install();};cancel.Click+=delegate{if(working){if(cancellation!=null)cancellation.Cancel();status.Text="正在取消下载，请稍候…";}else Close();};FormClosing+=delegate(object sender,FormClosingEventArgs e){if(working){e.Cancel=true;if(cancellation!=null)cancellation.Cancel();}};Shown+=async delegate{await Check();};
 }
 void Busy(bool value){working=value;check.Enabled=!value;install.Enabled=!value&&release!=null&&UpdateCore.ParseVersion(release.Version)>UpdateCore.CurrentVersion;cancel.Text=value?"取消":"关闭";}
 async Task Check(){if(working)return;release=null;Busy(true);status.Text="正在连接 GitHub 检查最新版本…";progress.Style=ProgressBarStyle.Marquee;try{release=await Task.Run(()=>UpdateCore.Check());bool newer=UpdateCore.ParseVersion(release.Version)>UpdateCore.CurrentVersion;status.Text=newer?"发现新版本 v"+release.Version+"，下载完成后会提示保存并重新启动。":"当前已是最新版本，无需更新。";notes.Text=String.IsNullOrWhiteSpace(release.Notes)?"暂无版本说明。":release.Notes;}catch(Exception ex){status.Text=UpdateCore.Friendly(ex);notes.Text="检查失败不影响继续使用；可稍后点击“检查更新”重试。";}finally{progress.Style=ProgressBarStyle.Blocks;progress.Value=0;Busy(false);}}
 async Task Install(){if(working||release==null)return;Busy(true);cancellation=new CancellationTokenSource();progress.Value=0;status.Text="正在下载 v"+release.Version+"，下载期间不会替换程序…";try{var report=new Progress<int>(v=>{if(!IsDisposed)progress.Value=Math.Min(100,v);});string plan=await Task.Run(()=>UpdateCore.Prepare(release,target,data,report,cancellation.Token));cancellation.Token.ThrowIfCancellationRequested();status.Text="下载与校验完成，正在确认保存状态…";if(await start(plan)){working=false;DialogResult=DialogResult.OK;Close();}else status.Text="已取消安装，继续保留当前程序与编辑。";}catch(OperationCanceledException){status.Text="已取消下载，当前程序与订单保持不变。";}catch(Exception ex){status.Text=UpdateCore.Friendly(ex);}finally{cancellation.Dispose();cancellation=null;if(!IsDisposed)Busy(false);}}
}
